import{_ as o,o as t,c as s,ag as i}from"./chunks/framework.DQQHyi2x.js";const h=JSON.parse('{"title":"Presence Dashboard: Status Accuracy Improvements","description":"","frontmatter":{},"headers":[],"relativePath":"plans/2026-03-08-presence-status-accuracy.md","filePath":"plans/2026-03-08-presence-status-accuracy.md"}'),a={name:"plans/2026-03-08-presence-status-accuracy.md"};function n(r,e,l,d,c,u){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="presence-dashboard-status-accuracy-improvements" tabindex="-1">Presence Dashboard: Status Accuracy Improvements <a class="header-anchor" href="#presence-dashboard-status-accuracy-improvements" aria-label="Permalink to &quot;Presence Dashboard: Status Accuracy Improvements&quot;">​</a></h1><p><strong>Date:</strong> 2026-03-08 <strong>Status:</strong> Implemented</p><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to &quot;Problem&quot;">​</a></h2><p>The Presence Dashboard cards don&#39;t show useful status information for most sessions. From a screenshot with 8 sessions:</p><ul><li><strong>5 of 8 cards are nearly empty</strong> — openclaw, both nano-banana-pipelines, claude-deck, and linode-migration show only a tiny activity sparkline with no narrative, commands, or files.</li><li><strong>&quot;Active: 0&quot; despite 8 sessions listed</strong> — the 5-minute idle timeout aggressively marks sessions as idle even when Claude is actively thinking (just not triggering hook events).</li><li><strong>No status text</strong> — the only indicator is a colored dot (green/gray/red), which doesn&#39;t communicate what the session is actually doing.</li></ul><h3 id="root-cause" tabindex="-1">Root Cause <a class="header-anchor" href="#root-cause" aria-label="Permalink to &quot;Root Cause&quot;">​</a></h3><p>The current status model has 4 states (<code>active</code>, <code>idle</code>, <code>error</code>, <code>stopped</code>) derived from <strong>event timing</strong>, not from what Claude is actually doing:</p><ul><li>A session is <code>active</code> only while hook events are arriving frequently (&lt; 5 min apart)</li><li>A session becomes <code>idle</code> after 5 minutes without events — but Claude may be thinking, waiting for a large tool response, or the user is reading output</li><li>Cards render sections conditionally (<code>last_narrative</code>, <code>modified_files</code>, <code>last_command</code>), so sessions that haven&#39;t triggered those specific events appear blank</li><li>There&#39;s no human-readable status text — just a dot color</li></ul><h3 id="relevant-code" tabindex="-1">Relevant Code <a class="header-anchor" href="#relevant-code" aria-label="Permalink to &quot;Relevant Code&quot;">​</a></h3><p><strong>Backend status logic</strong> (<code>backend/app/services/presence_service.py</code>):</p><ul><li><code>_mark_idle_sessions()</code>: marks any <code>active</code> session as <code>idle</code> if <code>last_event_at</code> is &gt; 5 minutes ago</li><li><code>process_event()</code>: sets status to <code>active</code> on any non-Stop/SessionEnd event, <code>stopped</code> on Stop/SessionEnd, <code>error</code> on non-zero Bash exit code</li><li>No concept of &quot;waiting for input&quot; vs &quot;thinking&quot; vs &quot;running tool&quot;</li></ul><p><strong>Frontend card rendering</strong> (<code>frontend/src/features/presence/PresenceCard.tsx</code>):</p><ul><li>Narrative section: only rendered if <code>session.last_narrative</code> exists</li><li>Modified files section: only rendered if <code>session.modified_files</code> has entries</li><li>Last command section: only rendered if <code>session.last_command</code> exists</li><li>When none of these exist, only the header (label + duration) and sparkline are shown</li></ul><p><strong>Hook events subscribed</strong> (from ConnectDialog):</p><ul><li><code>Notification</code> — narrative text updates</li><li><code>PostToolUse</code> — file edits, bash commands</li><li><code>Stop</code> — session paused</li><li><code>SessionStart</code> — session started</li><li><code>SessionEnd</code> — session ended</li></ul><hr><h2 id="proposed-solutions" tabindex="-1">Proposed Solutions <a class="header-anchor" href="#proposed-solutions" aria-label="Permalink to &quot;Proposed Solutions&quot;">​</a></h2><h3 id="approach-a-richer-status-from-existing-hooks-recommended" tabindex="-1">Approach A: Richer Status from Existing Hooks (Recommended) <a class="header-anchor" href="#approach-a-richer-status-from-existing-hooks-recommended" aria-label="Permalink to &quot;Approach A: Richer Status from Existing Hooks (Recommended)&quot;">​</a></h3><p><strong>Effort:</strong> Medium | <strong>Impact:</strong> High | <strong>Risk:</strong> Low</p><p>Derive a human-readable <code>status_text</code> from the last event and always display it prominently on every card. No new dependencies or hook types needed.</p><p><strong>Backend changes:</strong></p><ul><li>Add <code>status_text</code> field to <code>PresenceSession</code> model (string, e.g., &quot;Waiting for input&quot;, &quot;Ran tool: Bash&quot;, &quot;Edited 3 files&quot;, &quot;Thinking...&quot;)</li><li>Update <code>process_event()</code> to set <code>status_text</code> based on event type: <ul><li><code>Notification</code> with &quot;waiting for input&quot; → &quot;Waiting for input&quot;</li><li><code>PostToolUse</code> with <code>tool_name=Bash</code> → &quot;Ran: <code>&lt;command snippet&gt;</code>&quot;</li><li><code>PostToolUse</code> with <code>tool_name=Edit/Write</code> → &quot;Edited <code>&lt;filename&gt;</code>&quot;</li><li><code>PostToolUse</code> with other tools → &quot;Used tool: <code>&lt;tool_name&gt;</code>&quot;</li><li><code>SessionStart</code> → &quot;Session started&quot;</li><li><code>Stop</code>/<code>SessionEnd</code> → &quot;Stopped&quot;</li></ul></li><li>Replace binary idle detection with graduated staleness: <ul><li>Show <code>last_event_at</code> as relative time (&quot;2m ago&quot;, &quot;15m ago&quot;) on every card</li><li>Consider a longer idle timeout (15-20 min) or remove it entirely in favor of showing the &quot;last seen&quot; time</li></ul></li></ul><p><strong>Frontend changes:</strong></p><ul><li>Always show a status line on every card, even when no narrative/files/commands exist:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[●] mercadona-cli                    11h 39m</span></span>
<span class="line"><span>Waiting for input · last event 2m ago</span></span></code></pre></div></li><li>Show <code>status_text</code> prominently below the header (not conditionally)</li><li>Show relative <code>last_event_at</code> time alongside status</li><li>Consider showing <code>total_events</code> count as a secondary indicator of session activity</li></ul><p><strong>Why recommended:</strong> Gets 80% of the value with minimal changes. Every card will always show meaningful information. The &quot;last event&quot; time gives users an accurate sense of liveness without needing more hook types.</p><hr><h3 id="approach-b-poll-claude-code-status-directly" tabindex="-1">Approach B: Poll Claude Code Status Directly <a class="header-anchor" href="#approach-b-poll-claude-code-status-directly" aria-label="Permalink to &quot;Approach B: Poll Claude Code Status Directly&quot;">​</a></h3><p><strong>Effort:</strong> High | <strong>Impact:</strong> Very High | <strong>Risk:</strong> Medium</p><p>Add a backend polling mechanism that checks the actual state of Claude Code sessions independently of hook events.</p><p><strong>How it would work:</strong></p><ul><li>Backend periodically (every 10-30s) checks tmux panes for sessions known to be in tmux</li><li>Parse the tmux pane content to detect Claude Code status bar patterns (e.g., &quot;Thinking...&quot;, &quot;● claude-deck&quot;, idle prompt)</li><li>Could also check process status (is the Claude Code process still running?)</li><li>Update session status based on polled state, not just hook events</li></ul><p><strong>Pros:</strong></p><ul><li>Most accurate real-time status — doesn&#39;t depend on hooks firing</li><li>Can detect when Claude is thinking (no hooks fire during inference)</li><li>Can detect crashed/hung sessions</li></ul><p><strong>Cons:</strong></p><ul><li>Requires tmux dependency (not all sessions may use tmux)</li><li>Parsing terminal content is fragile</li><li>Adds background polling complexity</li><li>May duplicate CC Bridge functionality</li></ul><hr><h3 id="approach-c-subscribe-to-additional-hook-events" tabindex="-1">Approach C: Subscribe to Additional Hook Events <a class="header-anchor" href="#approach-c-subscribe-to-additional-hook-events" aria-label="Permalink to &quot;Approach C: Subscribe to Additional Hook Events&quot;">​</a></h3><p><strong>Effort:</strong> Medium | <strong>Impact:</strong> High | <strong>Risk:</strong> Low-Medium</p><p>Claude Code supports more hook events than currently subscribed. Adding more events gives finer-grained status.</p><p><strong>Additional events to consider:</strong></p><ul><li><code>PreToolUse</code> — fires before a tool runs, so we know Claude is about to execute something</li><li><code>UserMessage</code> — fires when the user sends a message, confirming the session is interactive</li><li><code>SubagentStart</code>/<code>SubagentEnd</code> — track when subagents are spawned</li></ul><p><strong>How it improves status:</strong></p><ul><li><code>PreToolUse</code> → status: &quot;Running tool: <code>&lt;name&gt;</code>...&quot; (before it completes)</li><li><code>UserMessage</code> → status: &quot;Processing user message...&quot; / resets idle timer</li><li>Gap between <code>PreToolUse</code> and <code>PostToolUse</code> → &quot;Tool running...&quot; with elapsed time</li><li>Long gap after <code>PostToolUse</code> with no new events → &quot;Thinking...&quot; (Claude is generating)</li></ul><p><strong>Pros:</strong></p><ul><li>More accurate status without polling</li><li>Leverages existing hook infrastructure</li><li>Can detect &quot;thinking&quot; state (gap between events)</li></ul><p><strong>Cons:</strong></p><ul><li>Requires user to update their hook configuration (re-run connect dialog)</li><li>More events = more webhook traffic</li><li>Still can&#39;t detect truly idle vs. thinking if no events fire</li></ul><hr><h2 id="recommendation" tabindex="-1">Recommendation <a class="header-anchor" href="#recommendation" aria-label="Permalink to &quot;Recommendation&quot;">​</a></h2><p><strong>Start with Approach A</strong>, then layer in Approach C later if needed.</p><p>Approach A is the quickest path to useful cards — every card will always show what the session last did and when. The &quot;last event X ago&quot; pattern is well-understood from tools like <code>kubectl get pods</code> (showing age) and gives users an intuitive sense of liveness.</p><p>Approach C can be added incrementally to get finer-grained &quot;Running tool...&quot; / &quot;Thinking...&quot; states, but it requires users to update their hook config, so it&#39;s better as a follow-up.</p><p>Approach B should only be considered if the tmux-based CC Bridge is always available and the polling approach can be shared between features.</p>`,53)])])}const g=o(a,[["render",n]]);export{h as __pageData,g as default};
